-- Aggregate integer amounts retain exact decimal values beyond the JavaScript safe range.
grant create on schema api,finance_private to git_tutor_commands;
create function finance_private.finance_json_total(p_value numeric)returns jsonb language plpgsql immutable set search_path='' as $$begin
 if p_value is null or p_value<>trunc(p_value)or length(trunc(p_value)::text)>100 then raise exception'AMOUNT_OUT_OF_RANGE';end if;
 if p_value between -9007199254740991 and 9007199254740991 then return to_jsonb(p_value::bigint);end if;return to_jsonb(trunc(p_value)::text);
end$$;
alter function finance_private.finance_json_total(numeric)owner to git_tutor_commands;
revoke all on function finance_private.finance_json_total(numeric)from public,anon,authenticated,service_role,git_tutor_worker;
create or replace function api.get_finance_summary(p_from date,p_to date,p_as_of timestamptz)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();bounds record;period jsonb;balances jsonb;balanced boolean;entries integer;begin
 perform app_private.require_role(actor,'admin');select * into bounds from finance_private.finance_report_range(p_from,p_to,p_as_of);
 with totals as(select l.account_code,sum(l.signed_minor)amount,coalesce(sum(l.signed_minor)filter(where l.signed_minor>0),0)inflow,coalesce(sum(-l.signed_minor)filter(where l.signed_minor<0),0)outflow from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at>=bounds.period_start and t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff group by l.account_code),report_values as(select
 -coalesce((select amount from totals where account_code='tuition_revenue'),0)revenue,coalesce((select amount from totals where account_code='tutor_expense'),0)tutor,coalesce((select amount from totals where account_code='operating_expense'),0)operating,coalesce((select amount from totals where account_code='promotional_subsidy_expense'),0)subsidy,
 coalesce((select inflow from totals where account_code='channel_cash'),0)inflow,coalesce((select outflow from totals where account_code='channel_cash'),0)outflow,coalesce((select amount from totals where account_code='channel_cash'),0)cash)
 select jsonb_build_object('earned_revenue_minor',finance_private.finance_json_total(revenue),'tutor_expense_minor',finance_private.finance_json_total(tutor),'operating_expense_minor',finance_private.finance_json_total(operating),'promotional_subsidy_minor',finance_private.finance_json_total(subsidy),'operating_profit_minor',finance_private.finance_json_total(revenue-tutor-operating-subsidy),'cash_inflow_minor',finance_private.finance_json_total(inflow),'cash_outflow_minor',finance_private.finance_json_total(outflow),'net_cash_movement_minor',finance_private.finance_json_total(cash))into period from report_values;
 with totals as(select l.account_code,sum(l.signed_minor)amount from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff group by l.account_code)
 select jsonb_build_object('cash_minor',finance_private.finance_json_total(coalesce((select amount from totals where account_code='channel_cash'),0)),'receivable_minor',finance_private.finance_json_total(coalesce((select amount from totals where account_code='receivable'),0)),
 'customer_credit_minor',finance_private.finance_json_total(-coalesce((select amount from totals where account_code='unapplied_customer_funds'),0)),'deferred_tuition_minor',finance_private.finance_json_total(-coalesce((select amount from totals where account_code='deferred_tuition'),0)),'package_obligation_minor',finance_private.finance_json_total(-coalesce((select amount from totals where account_code='deferred_package_obligation'),0)),
 'cancellation_obligation_minor',finance_private.finance_json_total(-coalesce((select amount from totals where account_code='deferred_cancellation_obligation'),0)),'tutor_payable_minor',finance_private.finance_json_total(-coalesce((select amount from totals where account_code='tutor_payable'),0)),'expense_payable_minor',finance_private.finance_json_total(-coalesce((select amount from totals where account_code='expense_payable'),0)))into balances;
 select coalesce(sum(l.signed_minor),0)=0,count(*)filter(where t.effective_at>=bounds.period_start)::integer into balanced,entries from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff;
 return jsonb_build_object('from',p_from,'to',p_to,'as_of',p_as_of,'currency','EGP','time_zone','Africa/Cairo','grain','ledger_line','period',period,'balances',balances,'ledger_balanced',balanced,'source_entry_count',entries);
end$$;
create or replace function api.list_finance_entries(p_from date,p_to date,p_as_of timestamptz,p_account_codes text[]default'{}',p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();bounds record;items jsonb;lastid uuid;begin
 perform app_private.require_role(actor,'admin');select * into bounds from finance_private.finance_report_range(p_from,p_to,p_as_of);if p_limit not between 1 and 100 or p_account_codes is null or cardinality(p_account_codes)>12 or not p_account_codes<@array['channel_cash','receivable','unapplied_customer_funds','deferred_tuition','deferred_package_obligation','deferred_cancellation_obligation','tuition_revenue','tutor_expense','tutor_payable','operating_expense','expense_payable','promotional_subsidy_expense']then raise exception'VALIDATION_ERROR';end if;
 if p_cursor is not null and not exists(select 1 from finance_private.ledger_lines where id=p_cursor)then raise exception'NOT_FOUND';end if;
 select coalesce(jsonb_agg(x.item order by x.recorded_at desc,x.id desc),'[]'::jsonb)into items from(select l.id,l.recorded_at,jsonb_build_object('line_id',l.id,'transaction_id',t.id,'source_type',t.source_type,'source_id',t.source_id,'account_code',l.account_code,'signed_minor',l.signed_minor,'currency',l.currency,'effective_at',t.effective_at,'recorded_at',t.recorded_at,'charge_id',l.charge_id,'enrollment_id',l.enrollment_id,'receiving_account_id',l.receiving_account_id)item from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at>=bounds.period_start and t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff and(cardinality(p_account_codes)=0 or l.account_code=any(p_account_codes))and(p_cursor is null or(l.recorded_at,l.id)<(select c.recorded_at,c.id from finance_private.ledger_lines c where c.id=p_cursor))order by l.recorded_at desc,l.id desc limit p_limit)x;
 if jsonb_array_length(items)=p_limit then lastid:=(items->(p_limit-1)->>'line_id')::uuid;end if;return jsonb_build_object('items',items,'next_cursor',lastid);
end$$;
revoke create on schema api,finance_private from git_tutor_commands;
